  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archer-(Guerrier).html&quot; title=&quot;Archer&quot;&gt;Archer&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Castagneur-(Guerrier).html&quot; title=&quot;Castagneur&quot;&gt;Castagneur&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Du-Marteau-(Guerrier).html&quot; title=&quot;Champion du marteau&quot;&gt;Champion du marteau&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Nain.html&quot; title=&quot;Les nains&quot;&gt;Nain&lt;/a&gt;) (MR)&lt;/li&gt;
