  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Embusqueur-Des-Airs-(Guerrier).html&quot; title=&quot;Embusqueur des airs&quot;&gt;Embusqueur des airs&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Strix-(Race).html&quot; title=&quot;Les strix&quot;&gt;Strix&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Frappe-Tonnerre-(Guerrier).html&quot; title=&quot;Frappe-tonnerre&quot;&gt;Frappe-tonnerre&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Occulte-(Guerrier).html&quot; title=&quot;Gardien occulte&quot;&gt;Gardien occulte&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gladiateur-(Guerrier).html&quot; title=&quot;Gladiateur&quot;&gt;Gladiateur&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-D&#233;sarm&#233;-(Guerrier).html&quot; title=&quot;Guerrier d&#233;sarm&#233;&quot;&gt;Guerrier d&#233;sarm&#233;&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Mobile-(Guerrier).html&quot; title=&quot;Guerrier mobile&quot;&gt;Guerrier mobile&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Mutag&#233;nique-(Guerrier).html&quot; title=&quot;Guerrier mutag&#233;nique&quot;&gt;Guerrier mutag&#233;nique&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Nomade-Au-Style-Libre-(Guerrier).html&quot; title=&quot;Guerrier nomade au style libre&quot;&gt;Guerrier nomade au style libre&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Sauvage-(Guerrier).html&quot; title=&quot;Guerrier sauvage&quot;&gt;Guerrier sauvage&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier-Sensitif-(Guerrier).html&quot; title=&quot;Guerrier sensitif&quot;&gt;Guerrier sensitif&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invincible-(Guerrier).html&quot; title=&quot;Invincible&quot;&gt;Invincible&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Maitre-Darmes-(Guerrier).html&quot; title=&quot;Ma&#238;tre d&amp;#39;armes&quot;&gt;Ma&#238;tre d&#39;armes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Dhast-(Guerrier).html&quot; title=&quot;Ma&#238;tre d&amp;#39;hast&quot;&gt;Ma&#238;tre d&#39;hast&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Armures-(Guerrier).html&quot; title=&quot;Ma&#238;tre des armures&quot;&gt;Ma&#238;tre des armures&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Reliques-(Guerrier).html&quot; title=&quot;Ma&#238;tre des reliques&quot;&gt;Ma&#238;tre des reliques&lt;/a&gt; (&lt;i&gt;WMH&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Du-Bouclier-(Guerrier).html&quot; title=&quot;Ma&#238;tre du bouclier&quot;&gt;Ma&#238;tre du bouclier&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Martial-(Guerrier).html&quot; title=&quot;Ma&#238;tre martial&quot;&gt;Ma&#238;tre martial&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Malotru-(Guerrier).html&quot; title=&quot;Malotru&quot;&gt;Malotru&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Monteur-De-B&#234;tes-(Guerrier).html&quot; title=&quot;Monteur de b&#234;tes&quot;&gt;Monteur de b&#234;tes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Phalange-(Guerrier).html&quot; title=&quot;Phalange&quot;&gt;Phalange&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sp&#233;cialiste-Du-Pavois-(Guerrier).html&quot; title=&quot;Sp&#233;cialiste du pavois&quot;&gt;Sp&#233;cialiste du pavois&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tacticien-(Guerrier).html&quot; title=&quot;Tacticien&quot;&gt;Tacticien&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tireur-Embusqu&#233;-Des-Cavernes-(Guerrier).html&quot; title=&quot;Tireur embusqu&#233; des cavernes&quot;&gt;Tireur embusqu&#233; des cavernes&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Drow-(Race).html&quot; title=&quot;Les drows&quot;&gt;Drow&lt;/a&gt;) (MR)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;script&gt;
$(function () {
  let image = &quot;Illustrations/PNJ/Drow.jpg&quot;;
  if(image == &quot;&quot; || image == &quot; &quot;) { $(&#39;.symbole2&#39;).html(&quot;&quot;); }
});
&lt;/script&gt;
&lt;div class=&quot;presentation navmenudroite&quot; style=&quot;margin-bottom:5px&quot;&gt;
&lt;table width=&quot;80px&quot;&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td class=&quot;symbole2&quot;&gt;&lt;abbr title=&quot;Cette option est plus sp&#233;cifique, voire r&#233;serv&#233;e, aux membres de la race indiqu&#233;e. Discutez avec votre MJ de sa disponibilit&#233; pour votre personnage.&quot;&gt;&lt;a href=&quot;./Pathfinder-RPG.Drow (race).ashx&quot;&gt;&lt;img src=&quot;/wiki/public/upload/Illustrations/PNJ/Drow.jpg&quot; width=&quot;80%&quot; style=&quot;float:center; margin: 0px -50px 0px 7px; border: 1px solid #4b3124&quot;&gt;&lt;/a&gt;&lt;/abbr&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;
&lt;td&gt;&lt;div style=&quot;text-align:center; font-size: 81%; font-weight: bold;&quot;&gt;Option plus&lt;br /&gt;commune chez&lt;br /&gt;les &lt;a class=&quot;pagelink&quot; href=&quot;Drow-(Race).html&quot; title=&quot;Les drows&quot;&gt;drows&lt;/a&gt;.&lt;/div&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Manuel des races (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Advanced Race Guide, Elves of Golarion, Gnomes of Golarion, Goblins of Golarion, Halflings of Golarion, Humans of Golarion, Dwarves of Golarion, Orcs of Golarion/Manuel des races&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoMR.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
&lt;div class=&quot;description&quot;&gt;&lt;b&gt;Note&lt;/b&gt; : Cet arch&#233;type de classe peut &#233;galement &#234;tre utilis&#233; avec la variante de classe &lt;a class=&quot;pagelink&quot; href=&quot;Pistolier.html&quot; title=&quot;Le pistolier&quot;&gt;pistolier&lt;/a&gt;. La capacit&#233; qui remplace la capacit&#233; Courage remplacera &#224; la place la capacit&#233; D&#233;robade. Les capacit&#233;s rempla&#231;ant l&#39;entra&#238;nement aux armes remplaceront &#224; la place l&#39;entra&#238;nement aux armes &#224; feu. Projectile impr&#233;gn&#233; pourra &#234;tre utilis&#233; sur les balles.&lt;/div&gt;&lt;br /&gt;&lt;i&gt;Parfaitement &#224; l’aise dans les t&#233;n&#232;bres, le tireur embusqu&#233; des cavernes compte sur sa discr&#233;tion et les attaques &#224; distance combin&#233;es &#224; ses pouvoirs magiques pour harceler ses adversaires. Il mise sur la surprise, ses capacit&#233;s magiques inn&#233;es et le poison pour d&#233;faire les ennemis imprudents.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences de classe.&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_de_classe_0&quot; href=&quot;#Comp&#233;tences_de_classe_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le tireur embusqu&#233; des cavernes ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; &#224; sa liste de comp&#233;tences de classe, mais en retire &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;. &lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Projectile impr&#233;gn&#233; (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Projectile_impr&#233;gn&#233;_Sur_1&quot; href=&quot;#Projectile_impr&#233;gn&#233;_Sur_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 1, le tireur embusqu&#233; des cavernes gagne la capacit&#233; &#224; impr&#233;gner ses fl&#232;ches ou ses carreaux de l’effet de l’un de ses pouvoirs magiques drows par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; : &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lueur-F&#233;erique.html&quot; title=&quot;Lueur f&#233;erique&quot;&gt;lueur f&#233;erique&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;n&#232;bres.html&quot; title=&quot;T&#233;n&#232;bres&quot;&gt;t&#233;n&#232;bres&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;n&#232;bres-Profondes.html&quot; title=&quot;T&#233;n&#232;bres profondes&quot;&gt;t&#233;n&#232;bres profondes&lt;/a&gt;&lt;/i&gt; (&#224; condition qu’il ait acc&#232;s au pouvoir). Lorsque le drow tire une fl&#232;che ou un carreau de ce genre, la zone d’effet du sort est centr&#233;e sur le point d’impact du projectile. Si la cible de l’attaque occupe un espace plus large que 1,5 m&#232;tre, le tireur embusqu&#233; des cavernes peut d&#233;cider quelle case de l’espace occup&#233; par la cr&#233;ature sera le centre de l’effet du pouvoir magique, tant que la case est dans la ligne de mire du tireur embusqu&#233;. &lt;br /&gt;&lt;br /&gt;Le tireur embusqu&#233; des cavernes peut aussi d&#233;cider de cibler une seule case situ&#233;e dans sa ligne de mire avec sa fl&#232;che ou son carreau impr&#233;gn&#233; et utiliser cette case comme le centre de la zone d’effet de son pouvoir magique sur une attaque r&#233;ussie (&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; 5). La fl&#232;che doit &#234;tre tir&#233;e pendant le round o&#249; elle a &#233;t&#233; impr&#233;gn&#233;e ou le pouvoir magique est g&#226;ch&#233;. Si la fl&#232;che ou le carreau manque la cible, le pouvoir magique est g&#226;ch&#233;. Cette capacit&#233; remplace le &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#DONSUPPLEMENTAIRE&quot; title=&quot;Le guerrier&quot;&gt;don&lt;/a&gt; que le guerrier gagne au niveau 1. &lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Tireur silencieux (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Tireur_silencieux_Ext_2&quot; href=&quot;#Tireur_silencieux_Ext_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 2, le tireur embusqu&#233; des cavernes gagne un bonus de +2 &#224; ses tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; lorsqu’il arme un arc ou une arbal&#232;te, empoisonne les munitions et tire. Ce bonus augmente de +2 tous les quatre niveaux au-del&#224; du second. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#COURAGE&quot; title=&quot;Le guerrier&quot;&gt;courage&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Rapide et mortel (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Rapide_et_mortel_Ext_3&quot; href=&quot;#Rapide_et_mortel_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, le tireur embusqu&#233; des cavernes peut se d&#233;placer &#224; sa vitesse maximale alors qu’il utilise &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; sans malus et peut appliquer du poison &#224; une seule fl&#232;che ou &#224; un seul carreau par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;. Cette capacit&#233; remplace le &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#DONSUPPLEMENTAIRE&quot; title=&quot;Le guerrier&quot;&gt;don suppl&#233;mentaire&lt;/a&gt; que le guerrier gagne au niveau 4. &lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Formation de tireur embusqu&#233; (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Formation_de_tireur_embusqu&#233;_Ext_4&quot; href=&quot;#Formation_de_tireur_embusqu&#233;_Ext_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 5, le tireur embusqu&#233; des cavernes choisit le &lt;a class=&quot;pagelink&quot; href=&quot;Groupe-Darmes.html&quot; title=&quot;Les groupes d&amp;#39;arme du guerrier&quot;&gt;groupe d’armes&lt;/a&gt; arc ou arbal&#232;te et gagne un bonus de +2 &#224; ses jets d’attaque et de d&#233;g&#226;ts. Ce bonus augmente de +1 tous les quatre niveaux apr&#232;s le 5e. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armes 1, 3 et 4&lt;/a&gt;. &lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Projectile impr&#233;gn&#233; sup&#233;rieur (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Projectile_impr&#233;gn&#233;_sup&#233;rieur_Sur_5&quot; href=&quot;#Projectile_impr&#233;gn&#233;_sup&#233;rieur_Sur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 9, le tireur embusqu&#233; des cavernes gagne deux utilisations suppl&#233;mentaires de ses pouvoirs magiques &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lueur-F&#233;erique.html&quot; title=&quot;Lueur f&#233;erique&quot;&gt;lueur f&#233;erique&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;n&#232;bres.html&quot; title=&quot;T&#233;n&#232;bres&quot;&gt;t&#233;n&#232;bres&lt;/a&gt;&lt;/i&gt;, mais ne peut se servir de ces deux utilisations bonus que pour impr&#233;gner des fl&#232;ches ou des carreaux avec sa capacit&#233; de classe projectile impr&#233;gn&#233;. Cette capacit&#233; remplace &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armes 2&lt;/a&gt;. &lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Ma&#238;trise des armes (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Ma&#238;trise_des_armes_Ext_6&quot; href=&quot;#Ma&#238;trise_des_armes_Ext_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 20, lorsque le tireur embusqu&#233; des cavernes gagne &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#MAITRISEDESARMES&quot; title=&quot;Le guerrier&quot;&gt;ma&#238;trise des armes&lt;/a&gt;, il doit choisir une arme du groupe des arcs ou des arbal&#232;tes.
